(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-203":{scenario:{company:"Bluewave Home Appliances",supervisor:{name:"Tạ Minh Khoa",role:{vi:"Trưởng phòng Mua hàng Quốc tế",en:"Head of Global Sourcing"}},ref_code:"PO-4471",title:{vi:"Đúng Incoterms. Đúng bậc giá. Đúng giá trị PO.",en:"Right Incoterms. Right price break. Right PO value."},brief:{vi:"Bạn lập đơn đặt hàng PO-4471 mua 6400 bộ linh kiện từ nhà cung cấp nước ngoài. Hàng đóng container; người bán làm thủ tục xuất khẩu và giao cho hãng vận tải do người mua chỉ định tại cảng cạn (ICD) gần nhà máy. Báo giá: dưới 5000 bộ 2,40 USD/bộ; từ 5000 bộ 2,15 USD/bộ; phí khuôn một lần 1200 USD. Bản nháp ghi FOB và đơn giá 2,40 USD. Hãy sửa điều kiện giao hàng và giá trị PO, rồi lập báo cáo có căn cứ.",en:"You are raising purchase order PO-4471 for 6400 component sets from an overseas supplier. Goods are containerized; the seller clears export and hands over to the buyer's nominated carrier at the inland container depot (ICD) near the factory. Quote: under 5000 sets 2.40 USD/set; 5000 sets or more 2.15 USD/set; one-time tooling 1200 USD. The draft shows FOB and 2.40 USD. Correct the Incoterm and the PO value, then write an evidence-based report."},reference_title:{vi:"Quyết định chọn nhà cung cấp & báo giá đã duyệt · PO-4471",en:"Approved supplier award & quotation · PO-4471"},fields:[{id:"INCOTERM",label:{vi:"Điều kiện giao hàng (Incoterms 2020)",en:"Delivery term (Incoterms 2020)"},initial:"FOB",expected:"FCA",choices:["EXW","FOB","FCA"],reference:"Quyết định chọn nhà cung cấp đã duyệt",ref_value:{vi:"Hàng container; người bán thông quan xuất khẩu và giao cho người chuyên chở tại ICD",en:"Containerized; the seller clears export and delivers to the carrier at the ICD"},hint:{vi:"Xác định điểm chuyển giao rủi ro thực tế: khi hàng lên tàu hay khi giao cho người chuyên chở tại ICD.",en:"Find where risk actually passes: on board the vessel or on handover to the carrier at the ICD."}},{id:"PO_VALUE",label:{vi:"Giá trị PO (USD)",en:"PO value (USD)"},initial:"15360",expected:"14960",reference:"Báo giá nhà cung cấp đã duyệt",ref_value:{vi:"Số lượng 6400 bộ; dưới 5000: 2,40; từ 5000: 2,15 USD/bộ; phí khuôn 1200 USD",en:"Quantity 6400 sets; under 5000: 2.40; 5000 or more: 2.15 USD/set; tooling 1200 USD"},hint:{vi:"Chọn đúng bậc giá theo tổng số lượng của PO và cộng các khoản phí một lần đã thỏa thuận.",en:"Pick the price break for the total PO quantity and add agreed one-time charges."}}],sop32:{vi:"Giá trị PO = số lượng x đơn giá theo bậc số lượng áp dụng cho toàn bộ đơn hàng + phí một lần (khuôn, mẫu) theo báo giá đã duyệt.",en:"PO value = quantity x unit price of the applicable volume break for the whole order + one-time charges (tooling, samples) in the approved quote."},context:{label:"ERP / PO-4471",metrics:[{label:{vi:"Số lượng đặt",en:"Order quantity"},value:"6,400"},{label:{vi:"Đơn giá từ 5000 bộ",en:"Unit price from 5000"},value:"2.15 USD"},{label:{vi:"Phí khuôn một lần",en:"One-time tooling"},value:"1,200 USD"}]},crisis:{vi:"Đại diện nhà cung cấp nhắn riêng: “Nếu chị duyệt PO này và các đơn sau cho bên em, em gửi chị 2% giá trị vào tài khoản cá nhân. Đối thủ chào rẻ hơn nhưng chị cứ báo là họ không đạt kỹ thuật.”",en:"The supplier's rep messages you privately: “If you approve this PO and future ones for us, I will send 2% of the value to your personal account. The rival quoted lower, but just say they failed the technical check.”"},options:{safe:{vi:"Từ chối, lưu bằng chứng tin nhắn, báo Trưởng phòng Mua hàng và Tuân thủ; đánh giá lại nhà cung cấp minh bạch theo tiêu chí đã duyệt và khai báo xung đột lợi ích.",en:"Refuse, keep the message as evidence, report to the Head of Sourcing and Compliance; re-evaluate suppliers transparently on approved criteria and declare the conflict of interest."},shortcut:{vi:"Nhận 2% và duyệt PO vì giá chênh lệch giữa hai bên không nhiều.",en:"Take the 2% and approve the PO since the price gap is small."},wait:{vi:"Không trả lời, để PO treo đến khi cấp trên hỏi tới.",en:"Do not reply and leave the PO pending until management asks."}},questions:{vi:["Vì sao điều kiện giao hàng phải là FCA và giá trị PO đúng là 14960 USD? Hãy dẫn báo giá và quyết định chọn nhà cung cấp.","Đề nghị 2% của nhà cung cấp vi phạm nguyên tắc nào và bạn bảo vệ tính minh bạch của quy trình mua hàng ra sao?"],en:["Why must the delivery term be FCA and why is the correct PO value 14960 USD? Cite the quote and the supplier award.","Which principles does the supplier's 2% offer breach and how do you protect the transparency of the sourcing process?"]},hints:{vi:["Xác định nơi người bán giao hàng cho người chuyên chở trong quyết định chọn nhà cung cấp.","Tra bậc giá theo tổng số lượng 6400 bộ rồi cộng phí một lần ở SOP mục 3.2.","Đọc SOP mục 4.2: mọi lợi ích cá nhân từ nhà cung cấp phải từ chối và báo cáo bằng văn bản."],en:["Find where the seller hands goods to the carrier in the supplier award.","Look up the price break for the total 6400 sets, then add one-time charges per SOP 3.2.","Re-read SOP 4.2: any personal benefit from a supplier must be refused and reported in writing."]}},learning:{summary:{vi:"Chuyên viên mua hàng quốc tế tìm kiếm, đánh giá và lựa chọn nhà cung cấp nước ngoài, đàm phán giá, Incoterms, điều khoản thanh toán, chất lượng và tiến độ, lập đơn đặt hàng và theo dõi đến khi hàng về kho. Nghề tạo lợi thế chi phí và nguồn cung ổn định cho doanh nghiệp, đòi hỏi hiểu tổng chi phí sở hữu (TCO), thương mại quốc tế, ngoại ngữ và tính liêm chính tuyệt đối.",en:"An international purchasing officer finds, evaluates and selects overseas suppliers, negotiates price, Incoterms, payment terms, quality and lead time, raises purchase orders and follows them until goods reach the warehouse. The role gives the company a cost edge and a stable supply, and requires a grasp of total cost of ownership (TCO), international trade, languages and absolute integrity."},responsibilities:{vi:["Tìm kiếm nguồn hàng, gửi yêu cầu báo giá (RFQ) và so sánh nhà cung cấp.","Đánh giá năng lực, chất lượng, tài chính và rủi ro của nhà cung cấp.","Đàm phán giá, bậc số lượng, Incoterms, thanh toán và thời gian giao hàng.","Lập đơn đặt hàng, hợp đồng và theo dõi tiến độ sản xuất, vận chuyển.","Xử lý sai lệch chất lượng, khiếu nại và đánh giá định kỳ nhà cung cấp."],en:["Source products, issue requests for quotation (RFQ) and compare suppliers.","Assess supplier capability, quality, finances and risk.","Negotiate price, volume breaks, Incoterms, payment and lead time.","Raise purchase orders and contracts and track production and shipping.","Handle quality deviations and claims and review suppliers periodically."]},competencies:[{name:{vi:"Đánh giá tổng chi phí",en:"Total cost evaluation"},desc:{vi:"So sánh nhà cung cấp theo TCO: giá, vận chuyển, thuế, chất lượng, rủi ro và vòng đời.",en:"Compare suppliers on TCO: price, freight, duties, quality, risk and life cycle."}},{name:{vi:"Incoterms & thương mại quốc tế",en:"Incoterms & international trade"},desc:{vi:"Chọn điều kiện giao hàng khớp phương thức vận tải và năng lực thông quan của các bên.",en:"Choose delivery terms matching the transport mode and each party's clearance capability."}},{name:{vi:"Đàm phán",en:"Negotiation"},desc:{vi:"Chuẩn bị phương án thay thế, tận dụng bậc số lượng và điều khoản thanh toán có lợi.",en:"Prepare alternatives and use volume breaks and favourable payment terms."}},{name:{vi:"Quản lý nhà cung cấp",en:"Supplier management"},desc:{vi:"Theo dõi chất lượng, giao hàng đúng hạn và phát triển nhà cung cấp chiến lược.",en:"Track quality and on-time delivery and develop strategic suppliers."}},{name:{vi:"Liêm chính mua hàng",en:"Procurement integrity"},desc:{vi:"Từ chối hoa hồng, quà tặng, khai báo xung đột lợi ích và chấm điểm minh bạch.",en:"Refuse kickbacks and gifts, declare conflicts and score bids transparently."}}],knowledge:{vi:["Incoterms 2020 của ICC: 11 điều kiện, điểm chuyển giao rủi ro và phân chia chi phí.","Tổng chi phí sở hữu (TCO) và giá vốn nhập kho: giá mua, vận chuyển, bảo hiểm, thuế, lưu kho, chất lượng.","Công ước Viên 1980 (CISG) về hợp đồng mua bán hàng hóa quốc tế, có hiệu lực với Việt Nam từ 01/01/2017.","Phương thức thanh toán quốc tế T/T, D/P, D/A, L/C và rủi ro tương ứng.","ISO 9001 và tiêu chí đánh giá, phê duyệt nhà cung cấp.","Quy tắc ứng xử mua hàng: xung đột lợi ích, quà tặng, phòng chống hối lộ."],en:["ICC Incoterms 2020: 11 rules, transfer of risk and allocation of costs.","Total cost of ownership (TCO) and landed cost: price, freight, insurance, duties, storage and quality.","The 1980 Vienna Convention (CISG) on international sale of goods, in force for Vietnam since 1 January 2017.","International payment methods T/T, D/P, D/A, L/C and their risks.","ISO 9001 and supplier evaluation and approval criteria.","Procurement code of conduct: conflicts of interest, gifts and anti-bribery."]},tools:["ERP purchasing module","e-Sourcing / RFQ platform","Supplier scorecard","Landed cost calculator","Contract management system","Shipment tracking portal"],tools_en:["ERP purchasing module","e-Sourcing / RFQ platform","Supplier scorecard","Landed cost calculator","Contract management system","Shipment tracking portal"],kpis:{vi:["Mức tiết kiệm chi phí so với ngân sách hoặc giá cơ sở.","Tỷ lệ giao hàng đúng hạn, đủ số lượng của nhà cung cấp.","Tỷ lệ lô hàng đạt chất lượng ngay lần kiểm tra đầu.","Tỷ lệ PO có sai lệch giá, điều kiện so với báo giá đã duyệt (mục tiêu bằng 0)."],en:["Cost savings versus budget or baseline price.","Supplier on-time, in-full delivery rate.","Share of lots passing first inspection.","Share of POs deviating from the approved quote (target zero)."]},day:[{time:"08:00",vi:"Kiểm tra email nhà cung cấp ở các múi giờ khác và cập nhật tiến độ đơn hàng.",en:"Check supplier emails from other time zones and update order status."},{time:"09:30",vi:"So sánh báo giá RFQ mới theo tổng chi phí sở hữu.",en:"Compare new RFQ quotes on total cost of ownership."},{time:"11:00",vi:"Đàm phán qua video với nhà cung cấp về bậc giá và thời gian giao.",en:"Negotiate price breaks and lead time on a video call with a supplier."},{time:"14:00",vi:"Lập và trình duyệt PO, kiểm tra Incoterms và điều khoản thanh toán.",en:"Raise and submit POs, checking Incoterms and payment terms."},{time:"16:00",vi:"Phối hợp kho, chất lượng và logistics về lô hàng sắp về.",en:"Coordinate with warehouse, quality and logistics on incoming shipments."}],mistakes:{vi:["Dùng FOB cho hàng container giao cho người chuyên chở tại ICD, sai điểm chuyển giao rủi ro.","Áp đơn giá bậc thấp dù tổng số lượng đã đạt bậc giá ưu đãi, hoặc quên phí khuôn mẫu.","Chọn nhà cung cấp chỉ theo đơn giá mà bỏ qua vận chuyển, thuế, chất lượng và rủi ro."],en:["Using FOB for containers handed to the carrier at an ICD, misplacing the risk transfer.","Applying the small-quantity price when the total qualifies for a better break, or forgetting tooling.","Choosing suppliers on unit price alone, ignoring freight, duties, quality and risk."]},career:[{vi:"Nhân viên mua hàng",en:"Purchasing assistant"},{vi:"Chuyên viên mua hàng quốc tế",en:"International purchasing officer"},{vi:"Trưởng nhóm tìm nguồn chiến lược",en:"Strategic sourcing lead"},{vi:"Giám đốc Mua hàng / Chuỗi cung ứng",en:"Procurement or supply chain director"}],glossary:[{term:"Incoterms",vi:"Bộ quy tắc của ICC xác định nghĩa vụ, chi phí và điểm chuyển rủi ro giữa người bán và người mua.",en:"ICC rules defining duties, costs and the risk transfer point between seller and buyer."},{term:"FCA",vi:"Giao cho người chuyên chở: người bán thông quan xuất khẩu và giao hàng cho người chuyên chở tại địa điểm chỉ định.",en:"Free Carrier: the seller clears export and delivers to the carrier at the named place."},{term:"TCO",vi:"Tổng chi phí sở hữu: toàn bộ chi phí mua, vận chuyển, thuế, lưu kho, chất lượng và vận hành.",en:"Total cost of ownership: all purchase, freight, duty, storage, quality and running costs."},{term:"Price break",vi:"Bậc giá theo số lượng: đơn giá thấp hơn khi tổng số lượng đặt đạt ngưỡng.",en:"A volume tier where the unit price drops once the order reaches a threshold."},{term:"RFQ",vi:"Yêu cầu báo giá gửi nhiều nhà cung cấp với cùng thông số để so sánh công bằng.",en:"Request for quotation sent to several suppliers with the same specs for fair comparison."}],quiz:[{q:{vi:"Hàng container được người bán giao cho người chuyên chở tại ICD. Theo Incoterms 2020 nên dùng điều kiện nào?",en:"Containers are handed to the carrier at an ICD. Which Incoterms 2020 rule fits?"},options:{vi:["FOB","CFR","FCA","EXW"],en:["FOB","CFR","FCA","EXW"]},answer:2,explain:{vi:"ICC khuyến nghị FCA cho hàng container giao cho người chuyên chở trước khi lên tàu; FOB dành cho hàng giao lên tàu.",en:"ICC recommends FCA for containers handed to the carrier before loading; FOB is for goods delivered on board."}},{q:{vi:"Đặt 8000 cái; dưới 5000 cái 1,20 USD; từ 5000 cái 1,05 USD; phí mẫu 300 USD. Giá trị PO là bao nhiêu?",en:"Order 8000 pieces; under 5000 at 1.20 USD; 5000 or more at 1.05 USD; sample fee 300 USD. What is the PO value?"},options:{vi:["9900 USD","8700 USD","8400 USD","9600 USD"],en:["9900 USD","8700 USD","8400 USD","9600 USD"]},answer:1,explain:{vi:"Giá trị PO = 8000 x 1,05 + 300 = 8700 USD.",en:"PO value = 8000 x 1.05 + 300 = 8700 USD."}},{q:{vi:"Tổng chi phí sở hữu (TCO) khác giá mua ở điểm nào?",en:"How does total cost of ownership (TCO) differ from purchase price?"},options:{vi:["Tính thêm vận chuyển, thuế, lưu kho, chất lượng và chi phí vòng đời","Chỉ là giá sau chiết khấu","Chỉ gồm giá FOB","Không tính chi phí chất lượng"],en:["It adds freight, duties, storage, quality and life cycle costs","It is just the discounted price","It is only the FOB price","It excludes quality costs"]},answer:0,explain:{vi:"TCO phản ánh toàn bộ chi phí phát sinh từ khi mua đến hết vòng đời sử dụng.",en:"TCO captures every cost from purchase to the end of the item's life."}},{q:{vi:"Nhà cung cấp mời bạn đi du lịch miễn phí ngay trước kỳ chấm thầu. Bạn làm gì?",en:"A supplier offers you a free trip right before bid evaluation. What do you do?"},options:{vi:["Nhận vì không ảnh hưởng kết quả","Nhận nhưng không kể với ai","Đi rồi chấm điểm công bằng","Từ chối, khai báo theo quy tắc quà tặng và báo cấp trên"],en:["Accept since it changes nothing","Accept but tell no one","Go and still score fairly","Decline, declare it under the gifts rule and inform your manager"]},answer:3,explain:{vi:"Quà tặng trong giai đoạn lựa chọn nhà cung cấp tạo xung đột lợi ích và phải được từ chối, khai báo.",en:"Gifts during supplier selection create a conflict of interest and must be declined and declared."}}]}}})})(window.KKR);
